class RequestValidationError(ValidationError):
    def __init__(
        self,
        errors: List[Dict[str, Any]],
        endpoint_metadata: Optional[Dict[str, Any]] = None,
    ) -> None:
        super().__init__(errors)
        self.endpoint_metadata = endpoint_metadata

    def __str__(self) -> str:
        message = super().__str__()
        if self.endpoint_metadata:
            metadata = self.endpoint_metadata
            message += f" (endpoint: {metadata['filepath']}:{metadata['lineno']} in {metadata['func_name']} {metadata['method']} {metadata['path']})"
        return message

